import pandas as pd, numpy as np, itertools
d=pd.read_csv('pool_pred.csv'); n=len(d)
rng=np.random.default_rng(3)
mu_s=d.shg_log.values; mu_g=d.gap_pred.values
grp=pd.factorize(d.formula)[0]; ng=grp.max()+1
sd_s,sd_g=0.36,0.53; fs=0.7
NS=2500
draws=[]
for it in range(NS):
    gs=rng.normal(0,sd_s*np.sqrt(fs),ng)[grp]+rng.normal(0,sd_s*np.sqrt(1-fs),n)
    gg=rng.normal(0,sd_g*np.sqrt(fs),ng)[grp]+rng.normal(0,sd_g*np.sqrt(1-fs),n)
    draws.append((np.clip(10**(mu_s+gs)-0.05,0,None), np.clip(mu_g+gg,0,None)))

def norms(S,G,scheme):
    if scheme=='lin':
        a=(S-S.min())/(S.max()-S.min())
    elif scheme=='log':
        L=np.log10(S+0.1); a=(L-L.min())/(L.max()-L.min())
    elif scheme=='rank':
        a=pd.Series(S).rank(pct=True).values
    b=(G-G.min())/(G.max()-G.min())
    if scheme=='rank': b=pd.Series(G).rank(pct=True).values
    return a,b

def build(scheme):
    A=np.array([norms(S,G,scheme)[0] for S,G in draws])
    B=np.array([norms(S,G,scheme)[1] for S,G in draws])
    return A,B
cache={s:build(s) for s in ['lin','log','rank']}

def hv(idx,A,B):
    s=A[:,idx]; g=B[:,idx]
    o=np.argsort(-s,axis=1)
    ss=np.take_along_axis(s,o,1); gg=np.take_along_axis(g,o,1)
    cum=np.maximum.accumulate(gg,1)
    prev=np.concatenate([np.zeros((A.shape[0],1)),cum[:,:-1]],1)
    return (ss*np.clip(cum-prev,0,None)).sum(1).mean()

def score(idx):
    vals={}
    for s in cache:
        A,B=cache[s]; vals[s]=hv(idx,A,B)
    # relative to best-possible for that scheme? just average of normalized-by-scheme scale
    return vals

# optimize each scheme separately, and a combined objective (mean of scheme scores each divided by its own oracle-ish scale)
scales={}
for s in cache:
    A,B=cache[s]
    sel=[]
    for k in range(5):
        sel.append(max(((hv(sel+[i],A,B),i) for i in range(n) if i not in sel))[1])
    cur=hv(sel,A,B); imp=True
    while imp:
        imp=False
        for pos in range(5):
            for i in range(n):
                if i in sel: continue
                tr=sel.copy(); tr[pos]=i; v=hv(tr,A,B)
                if v>cur+1e-6: cur,sel,imp=v,tr,True
    scales[s]=cur
    print(s,'best',round(cur,4),list(d.candidate_id[sel]), [f'{a:.0f}/{b:.1f}' for a,b in zip(d.shg_pred[sel],d.gap_pred[sel])])

def comb(idx):
    return np.mean([hv(idx,*cache[s])/scales[s] for s in cache])

sel=[]
for k in range(5):
    sel.append(max(((comb(sel+[i]),i) for i in range(n) if i not in sel))[1])
cur=comb(sel); imp=True
while imp:
    imp=False
    for pos in range(5):
        for i in range(n):
            if i in sel: continue
            tr=sel.copy(); tr[pos]=i; v=comb(tr)
            if v>cur+1e-6: cur,sel,imp=v,tr,True
print('COMBINED',round(cur,4))
print(d.iloc[sel][['candidate_id','formula','shg_pred','gap_pred']].to_string())
print({s:round(hv(sel,*cache[s])/scales[s],3) for s in cache})
