    gg=rng.normal(0,sd_g*np.sqrt(fs),ng)[grp]+rng.normal(0,sd_g*np.sqrt(1-fs),n)
    S[it]=np.clip(10**(mu_s+gs)-0.05,0,None); G[it]=np.clip(mu_g+gg,0,None)
def mk(scheme):
    if scheme=='lin': A=(S-S.min(1,keepdims=True))/(S.max(1,keepdims=True)-S.min(1,keepdims=True)); B=(G-G.min(1,keepdims=True))/(G.max(1,keepdims=True)-G.min(1,keepdims=True))
    if scheme=='log':
        L=np.log10(S+0.1); A=(L-L.min(1,keepdims=True))/(L.max(1,keepdims=True)-L.min(1,keepdims=True)); B=(G-G.min(1,keepdims=True))/(G.max(1,keepdims=True)-G.min(1,keepdims=True))
    if scheme=='rank': A=np.argsort(np.argsort(S,1),1)/(n-1); B=np.argsort(np.argsort(G,1),1)/(n-1)
    return A,B
cache={s:mk(s) for s in ['lin','log','rank']}
def hv(idx,A,B):
    s=A[:,idx]; g=B[:,idx]; o=np.argsort(-s,1)
    ss=np.take_along_axis(s,o,1); gg=np.take_along_axis(g,o,1)
    cum=np.maximum.accumulate(gg,1); prev=np.concatenate([np.zeros((NS,1)),cum[:,:-1]],1)
    return (ss*np.clip(cum-prev,0,None)).sum(1).mean()
scales={}
for s in cache:
    A,B=cache[s]; sel=[]
    for k in range(5): sel.append(max(((hv(sel+[i],A,B),i) for i in range(n) if i not in sel))[1])
    cur=hv(sel,A,B); imp=True
    while imp:
        imp=False
        for pos in range(5):
            for i in range(n):
                if i in sel: continue
                tr=sel.copy(); tr[pos]=i; v=hv(tr,A,B)
                if v>cur+1e-7: cur,sel,imp=v,tr,True
    scales[s]=cur
def comb(idx): return np.mean([hv(idx,*cache[s])/scales[s] for s in cache])
# unique-formula constraint
def ok(idx): return len(set(grp[idx]))==len(idx)
sel=[]
for k in range(5):
    cands=[(comb(sel+[i]),i) for i in range(n) if i not in sel and ok(sel+[i])]
    sel.append(max(cands)[1])
cur=comb(sel); imp=True
while imp:
    imp=False
    for pos in range(5):
        for i in range(n):
            if i in sel: continue
            tr=sel.copy(); tr[pos]=i
            if not ok(tr): continue
            v=comb(tr)
            if v>cur+1e-7: cur,sel,imp=v,tr,True
print('uniqueformula COMBINED',round(cur,4))
print(d.iloc[sel][['candidate_id','formula','shg_pred','gap_pred']].to_string())
for pos in range(5):
    o=[x for j,x in enumerate(sel) if j!=pos]
    print(d.candidate_id[sel[pos]],'marg',round(cur-comb(o),4))
# rank by marginal / order for ranked list
# also print top alternatives for each slot
for pos in range(5):
    o=[x for j,x in enumerate(sel) if j!=pos]
    alt=sorted(((comb(o+[i]),d.candidate_id[i]) for i in range(n) if i not in o and ok(o+[i])),reverse=True)[:4]
    print('slot',d.candidate_id[sel[pos]],[(c,round(v,4)) for v,c in alt])
